import{at as e,it as t,t as n,yt as r}from"./chunks/framework.Baq27OmJ.js";var i=JSON.parse(`{"title":"Commit Mock Cache Fixtures","description":"","frontmatter":{},"headers":[],"relativePath":"skills/contributors/commit-mock-cache-fixtures.md","filePath":"skills/contributors/commit-mock-cache-fixtures.md"}`),a={name:`skills/contributors/commit-mock-cache-fixtures.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="commit-mock-cache-fixtures" tabindex="-1">Commit Mock Cache Fixtures <a class="header-anchor" href="#commit-mock-cache-fixtures" aria-label="Permalink to “Commit Mock Cache Fixtures”">​</a></h1><p>Use this skill whenever a change in this repo adds or edits a test that calls <code>@warp-drive/holodeck</code>&#39;s mock helpers (<code>GET</code>, <code>POST</code>, <code>PUT</code>, <code>PATCH</code>, <code>DELETE</code>, <code>HEAD</code>, or <code>mock</code>), and before you finalize any commit or open a pull request that touches one. The fixtures those tests record are source code, and a local run will not tell you when you have left them behind.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to “Steps”">​</a></h2><ol><li>Run <code>git status</code> and look for new or modified paths under <code>**/.mock-cache/</code>.</li><li>Stage and commit every fixture that belongs to a test your change added or edited. The fixture is part of the change in the same way the test file is.</li><li>Leave unrelated <code>.mock-cache</code> churn alone. Fixtures that changed only because you ran an existing suite are pre-existing drift, not yours to fold into this pull request. Say so in the pull request instead of committing the noise.</li><li>Push, and let CI prove the fixtures replay, per <a href="./use-ci-as-the-source-of-truth">Use CI as the Source of Truth</a>. CI builds with <code>CI</code> set, so every test replays from <code>.mock-cache</code>, and a fixture you forgot to commit fails there as a missing mock. A local run without <code>CI</code> records whatever it needs and passes regardless, so it is not evidence that the fixtures are committed.</li><li>If you do check replay locally, run <code>CI=1 pnpm test</code> from the repository root, where <code>pnpm test</code> goes through turbo. Never run it from inside a test app&#39;s directory. <code>CI</code> is compiled into the test bundle by <code>build:tests</code>, and turbo is what notices the change and rebuilds. Run it in the app directory and it reuses the bundle already built in record mode, passes, and re-records the fixture you were trying to verify.</li></ol><h2 id="why-a-local-pass-means-nothing-here" tabindex="-1">Why a local pass means nothing here <a class="header-anchor" href="#why-a-local-pass-means-nothing-here" aria-label="Permalink to “Why a local pass means nothing here”">​</a></h2><p>Recording is the default outside CI. The switch lives in <code>warp-drive-packages/build-config/src/-private/utils/get-env.ts</code>:</p><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> SHOULD_RECORD</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Boolean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">!</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">CI</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> ||</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> IS_RECORDING</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>So every ordinary local run, including one an agent drives, writes fresh fixtures instead of validating against the committed ones. It does this silently. A test whose fixture was never committed goes green on your machine and fails in the first environment that enforces replay, with <code>No meta was found for ... You may need to record a mock for this request</code>.</p><p>The directories are hash-named and look like build output, which is the other half of the trap. <code>packages/holodeck/server/utils.js</code> states the rule in a code comment and nowhere else:</p><blockquote><p>the <code>.mock-cache</code> directory should be checked-in to the codebase</p></blockquote><p>Nothing enforces it. There is no lint rule, no CI check, and no gate that fails on a missing fixture. Treating these paths the way you would treat <code>dist/</code> is the single most common way to ship a test that only works on the machine that wrote it.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to “Notes”">​</a></h2><ul><li>Agent sessions are the usual offender, because staging only the files a task explicitly named is otherwise good practice.</li><li>Renaming a test or its module changes the test id, which orphans the old fixture directory and records a new one. Delete the orphan in the same commit.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to “Related”">​</a></h2><ul><li>Full guide: <a href="/pr-preview/pr-11286/guides/the-manual/testing/record-and-replay">Recording and Replaying</a></li><li>Related skill: <a href="/pr-preview/pr-11286/skills/holodeck/mock-http-requests-in-tests">Mock HTTP Requests in Tests</a></li></ul>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};